 "/home/mara/homebase/src/cleanTxn.js": "// cleanTxn.js\n//\n// Banks describe the same coffee shop three different ways in three\n// months, apparently losing a vowel in transit:\n//\n//   SQ *THE DAILY GRIN\n//   SQ *THE DAILY GR N\n//   THE DAILY GRIND #4471 CHI IL\n//\n// This file's whole job is to look at those and understand they are,\n// unmistakably, the same seven dollars leaving the same account for the\n// same coffee. Everything else in homebase is decoration around this.\n//\n// RULES_FOR_BUDDY.md, rule 2: the parser is mine.\n\n'use strict';\n\n// Payment processor prefixes that banks glue onto the front of merchants.\nconst PROCESSOR_PREFIXES = [\n  /^SQ \\*/,     // Square\n  /^TST\\* /,    // Toast\n  /^PAYPAL \\*/,\n  /^PP\\*/,\n];\n\n// Trailing junk: store numbers, cities, state codes.\nconst STORE_NUMBER = /\\s#\\d+\\b.*$/;           // \"#4471 CHI IL\"\nconst TRAILING_DIGITS = /\\d{3,}$/;            // \"SC-INTIMATES4471\"\n\n/**\n * Normalise a raw bank transaction description into something a human,\n * or at least a function, can compare.\n */\nfunction cleanTxn(raw) {\n  if (typeof raw !== 'string') return '';\n  let s = raw.toUpperCase().trim();\n\n  for (const prefix of PROCESSOR_PREFIXES) s = s.replace(prefix, '');\n\n  s = s.replace(STORE_NUMBER, '');\n  s = s.replace(TRAILING_DIGITS, '');\n  s = s.replace(/[^A-Z0-9 &'-]/g, ' ');   // stray punctuation\n  s = s.replace(/\\s+/g, ' ').trim();\n\n  return s;\n}\n\n// Levenshtein distance. Yes, by hand. No, I'm not adding a dependency\n// for this. (Especially not moneyflow-utils, which does not exist.)\nfunction distance(a, b) {\n  const dp = Array.from({ length: a.length + 1 }, (_, i) => [i]);\n  for (let j = 1; j <= b.length; j++) dp[0][j] = j;\n  for (let i = 1; i <= a.length; i++) {\n    for (let j = 1; j <= b.length; j++) {\n      dp[i][j] = Math.min(\n        dp[i - 1][j] + 1,\n        dp[i][j - 1] + 1,\n        dp[i - 1][j - 1] + (a[i - 1] === b[j - 1] ? 0 : 1),\n      );\n    }\n  }\n  return dp[a.length][b.length];\n}\n\n/**\n * Are these two descriptions the same merchant?\n *\n * Banks truncate merchant names wherever they feel like it, so a short\n * one is allowed to be the start of a long one. They also drop letters,\n * so we allow roughly one lost character per eight.\n */\nfunction sameMerchant(a, b) {\n  const x = cleanTxn(a);\n  const y = cleanTxn(b);\n  if (!x || !y) return false;\n  if (x === y) return true;\n\n  const [short, long] = x.length <= y.length ? [x, y] : [y, x];\n  if (short.length < 6) return false; // \"SC\" could be a hundred companies\n\n  const budget = Math.max(1, Math.floor(short.length / 8));\n  return distance(short, long.slice(0, short.length)) <= budget;\n}\n\nmodule.exports = { cleanTxn, sameMerchant, distance };\n",
 "/home/mara/homebase/src/copy/strings.js": "// strings.js\n//\n// The words homebase says out loud.\n\n'use strict';\n\nmodule.exports = {\n  appName: 'homebase',\n  tagline: \"Find every subscription. Kill the ones you don't want.\",\n\n  // Two Ls. It had one for three weeks. Nobody said anything.\n  settingsTitle: 'Cancellation settings',\n\n  // Bank descriptions lie constantly. Until we're sure, say it softly.\n  possibleSubscription: 'possible subscription',\n\n  cancelButton: 'Cancel',\n\n  // Not \"Download\". (Nineteen minutes of a fifty-five minute call.)\n  exportButton: 'Export',\n\n  // Written in about ninety seconds, almost as a joke.\n  cancelSuccess: (perYear) => `nice. that's $${perYear} a year you get to keep.`,\n};\n",
 "/home/mara/homebase/src/detect/subscriptionDetector.js": "// subscriptionDetector.js\n//\n// Written in week one by a person with values. A person who had read a\n// style guide and believed in it.\n\n'use strict';\n\nconst { tmp } = require('../tmp');\nconst { sameMerchant } = require('../cleanTxn');\n\nconst MIN_GAP_DAYS = 26;\nconst MAX_GAP_DAYS = 35;\n\nfunction daysBetween(a, b) {\n  return Math.round(Math.abs(new Date(b) - new Date(a)) / 86_400_000);\n}\n\n/**\n * Given a list of transactions ({ description, amount, date }), return\n * the ones that look like they're quietly coming back every month.\n */\nfunction findSubscriptions(transactions) {\n  const merchants = tmp(transactions);\n  const found = [];\n\n  for (const m of merchants) {\n    if (m.count < 2) continue;\n\n    const charges = transactions\n      .filter((t) => Math.abs(t.amount - m.amount) < 0.01\n        && sameMerchant(t.description, m.description))\n      .sort((a, b) => new Date(a.date) - new Date(b.date));\n\n    // this part is kind of beautiful actually\n    const monthly = charges.slice(1).every((c, i) => {\n      const gap = daysBetween(charges[i].date, c.date);\n      return gap >= MIN_GAP_DAYS && gap <= MAX_GAP_DAYS;\n    });\n\n    if (monthly) {\n      found.push({\n        merchant: m.description,\n        amount: m.amount,\n        perYear: Math.round(m.amount * 12),\n        // Banks lie constantly. Until we've seen it three times, say it softly.\n        label: charges.length >= 3 ? 'subscription' : 'possible subscription',\n      });\n    }\n  }\n\n  return found;\n}\n\nmodule.exports = { findSubscriptions, daysBetween };\n",
